class Solution:
    def wordBreak(self, s: str, wordDict: list[str]) -> bool:
        word_set = set(wordDict)
        def dfs(i: int) -> bool:
            if i == len(s):
                return True
            for j in range(i + 1, len(s) + 1):
                if s[i:j] in word_set and dfs(j):
                    return True
            return False
        return dfs(0)

