class Solution:
    def wordBreak(self, s: str, wordDict: list[str]) -> bool:
        word_set = set(wordDict)
        if not wordDict:
            return len(s) == 0
        max_len = max(len(w) for w in wordDict)
        n = len(s)
        dp = [False] * (n + 1)
        dp[0] = True
        for i in range(1, n + 1):
            for l in range(1, min(i, max_len) + 1):
                if not dp[i - l]:
                    continue
                if s[i - l:i] in word_set:
                    dp[i] = True
                    break
        return dp[n]

